import { Command, Fallback, runApp } from '@tuix/jsx'
import { $state } from '@tuix/reactive'

function Version() {
  return <text>1.0.0</text>
}

function Counter() {
  const count = $state(0, 'count')
  return (
    <box padding={1} border="rounded" gap={1}>
      <text>Count: {count()}</text>
      <button onClick={() => count.$set(count() + 1)}>Increment</button>
    </box>
  )
}

function App() {
  return (
    <>
      <Command name="version" description="Show version" component={Version} />
      <Command
        name="counter"
        description="Interactive counter"
        component={Counter}
        metadata={{ interactive: true }}
      />
      <Fallback component={() => <text>Use --help for commands</text>} />
    </>
  )
}

await runApp(App)

import { Box, Flex, Text, Button, Help, LargeText, Viewport } from '@tuix/ui'
import { runApp } from '@tuix/jsx'
import { $state } from '@tuix/reactive'

function Dashboard() {
  const open = $state(false, 'open')

  return (
    <Box padding={1} border="rounded" gap={1}>
      <LargeText color="cyan">TUIX</LargeText>
      <Text bold>Dashboard</Text>
      <Flex direction="row" gap={2}>
        <Button variant="primary" onClick={() => open.$set(!open())}>
          Toggle help
        </Button>
      </Flex>
      {open() ? (
        <Viewport width={60} height={8} showScrollbars>
          <Help
            title="Commands"
            entries={[
              { name: 'build', description: 'Build the project' },
              { name: 'test', description: 'Run tests' },
            ]}
          />
        </Viewport>
      ) : null}
    </Box>
  )
}

await runApp(Dashboard, { interactive: true })

import { ThemeProvider, useTheme, nordTheme } from '@tuix/themes'
import { Box, Text, Button } from '@tuix/ui'
import { runApp } from '@tuix/jsx'

function Panel() {
  const { theme, setThemeByName, themeNames } = useTheme()
  const t = theme()

  return (
    <Box padding={1} border="rounded" gap={1}>
      <Text color={t.colors.primary}>Theme: {t.name}</Text>
      <Text color={t.colors.fg}>Available: {themeNames().join(', ')}</Text>
      <Button onClick={() => setThemeByName('dark')}>Use dark</Button>
    </Box>
  )
}

function App() {
  return (
    <ThemeProvider
      config={{
        defaultTheme: 'nord',
        customThemes: { nord: nordTheme },
        allowSwitching: true,
      }}
    >
      <Panel />
    </ThemeProvider>
  )
}

await runApp(App, { interactive: true })
